import{_ as n,o as i,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Hukum Anti-Monopoli","description":"","frontmatter":{},"headers":[],"relativePath":"id/47-反垄断法.md","filePath":"id/47-反垄断法.md"}'),u={name:"id/47-反垄断法.md"};function s(r,a,l,k,o,d){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="hukum-anti-monopoli" tabindex="-1">Hukum Anti-Monopoli <a class="header-anchor" href="#hukum-anti-monopoli" aria-label="Permalink to &quot;Hukum Anti-Monopoli&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>47</td></tr><tr><td>Modul</td><td>Sistem Hukum dan Kerangka Tata Kelola</td></tr><tr><td>Kata kunci utama</td><td>Anti-Monopoli, Anti-Predasi, Persaingan Pasar, Monopoli Sumber Daya, Monopoli Kultivasi</td></tr></tbody></table><h2 id="i-tujuan-legislasi-dan-prinsip-dasar" tabindex="-1">I. Tujuan Legislasi dan Prinsip Dasar <a class="header-anchor" href="#i-tujuan-legislasi-dan-prinsip-dasar" aria-label="Permalink to &quot;I. Tujuan Legislasi dan Prinsip Dasar&quot;">​</a></h2><p>《Hukum Anti-Monopoli》 adalah salah satu dari lima hukum pendukung peradaban simbiosis jangkar, bertujuan untuk mencegah dan menghentikan praktik monopoli, melindungi persaingan pasar yang adil, meningkatkan efisiensi operasi ekonomi, menjaga kepentingan konsumen dan kepentingan publik sosial, serta mempromosikan perkembangan ekonomi simbiosis yang sehat. Dalam peradaban simbiosis jangkar, anti-monopoli tidak hanya ditujukan pada monopoli di bidang ekonomi tradisional, tetapi juga pada bentuk-bentuk khusus seperti monopoli sumber daya kultivasi, monopoli pengetahuan, dan monopoli bidang.</p><p>Hukum ini menetapkan prinsip dasar berikut:</p><table tabindex="0"><thead><tr><th>Prinsip</th><th>Isi</th></tr></thead><tbody><tr><td>Prinsip Persaingan Adil</td><td>Menjaga tatanan pasar persaingan yang adil, melarang praktik monopoli yang mengecualikan atau membatasi persaingan</td></tr><tr><td>Prinsip Anti-Predasi</td><td>Inti dari anti-monopoli adalah anti-predasi, mencegah monopolis mengeksploitasi kepentingan semua makhluk melalui posisi monopoli mereka</td></tr><tr><td>Prinsip Keterbukaan Sumber Daya</td><td>Sumber daya kultivasi publik dan pengetahuan dasar harus terbuka untuk seluruh masyarakat, dan monopoli swasta dilarang</td></tr><tr><td>Prinsip Keseimbangan Efisiensi dan Keadilan</td><td>Anti-monopoli harus melindungi efisiensi persaingan dan juga mencegah pemborosan sumber daya yang disebabkan oleh dispersi berlebihan</td></tr><tr><td>Prinsip Penerapan Antar Bidang</td><td>Hukum anti-monopoli berlaku untuk semua bidang dan pasar di dalam Hengyuanzhou, dan monopoli antar bidang juga diatur</td></tr></tbody></table><h2 id="ii-jenis-praktik-monopoli" tabindex="-1">II. Jenis Praktik Monopoli <a class="header-anchor" href="#ii-jenis-praktik-monopoli" aria-label="Permalink to &quot;II. Jenis Praktik Monopoli&quot;">​</a></h2><p>Praktik monopoli yang diatur oleh hukum ini mencakup empat jenis berikut:</p><h3 id="_1-perjanjian-monopoli" tabindex="-1">(1) Perjanjian Monopoli <a class="header-anchor" href="#_1-perjanjian-monopoli" aria-label="Permalink to &quot;(1) Perjanjian Monopoli&quot;">​</a></h3><p>Perjanjian monopoli merujuk pada perjanjian, keputusan, atau perilaku terkoordinasi lainnya yang mengecualikan atau membatasi persaingan, termasuk:</p><ol><li><strong>Perjanjian Monopoli Horizontal</strong>: Perjanjian antara pelaku usaha yang memiliki hubungan persaingan untuk menetapkan harga, membatasi produksi, membagi pasar, memboikot transaksi bersama, dll.</li><li><strong>Perjanjian Monopoli Vertikal</strong>: Perjanjian antara pelaku usaha dan lawan transaksi untuk menetapkan harga jual kembali, membatasi harga jual kembali minimum, dll.</li><li><strong>Perjanjian Monopoli Sumber Daya Kultivasi</strong>: Perjanjian antara sekte kultivasi untuk membagi wilayah sumber daya kultivasi, menyatukan harga sumber daya, membatasi pasokan sumber daya, dll.</li><li><strong>Perjanjian Monopoli Pengetahuan</strong>: Perjanjian antara lembaga pendidikan dan sekte kultivasi untuk memblokir metode kultivasi, membatasi penyebaran pengetahuan, menyatukan standar biaya kuliah, dll.</li></ol><h3 id="_2-penyalahgunaan-posisi-dominan-pasar" tabindex="-1">(2) Penyalahgunaan Posisi Dominan Pasar <a class="header-anchor" href="#_2-penyalahgunaan-posisi-dominan-pasar" aria-label="Permalink to &quot;(2) Penyalahgunaan Posisi Dominan Pasar&quot;">​</a></h3><p>Posisi dominan pasar merujuk pada posisi pasar di mana pelaku usaha memiliki kemampuan untuk mengontrol harga, jumlah, atau kondisi transaksi barang lainnya di pasar terkait, atau untuk menghambat atau memengaruhi masuknya pelaku usaha lain ke pasar terkait. Praktik penyalahgunaan posisi dominan pasar meliputi:</p><table tabindex="0"><thead><tr><th>Jenis Praktik</th><th>Manifestasi Spesifik</th></tr></thead><tbody><tr><td>Penetapan Harga Tidak Adil</td><td>Menjual barang dengan harga tidak adil tinggi atau membeli barang dengan harga tidak adil rendah</td></tr><tr><td>Penetapan Harga Predatori</td><td>Tanpa alasan yang sah, menjual barang dengan harga di bawah biaya untuk mengeliminasi pesaing</td></tr><tr><td>Penolakan Transaksi</td><td>Tanpa alasan yang sah, menolak untuk bertransaksi dengan lawan transaksi</td></tr><tr><td>Transaksi Eksklusif</td><td>Tanpa alasan yang sah, membatasi lawan transaksi untuk hanya bertransaksi dengan dirinya sendiri</td></tr><tr><td>Penjualan Terikat</td><td>Tanpa alasan yang sah, menjual barang terikat atau memaksakan kondisi tidak adil lainnya dalam transaksi</td></tr><tr><td>Perlakuan Diskriminatif</td><td>Tanpa alasan yang sah, menerapkan perlakuan diskriminatif dalam kondisi seperti harga transaksi kepada lawan transaksi dengan kondisi yang sama</td></tr><tr><td>Blokade Sumber Daya Kultivasi</td><td>Menggunakan posisi monopoli sumber daya kultivasi untuk menolak menyediakan sumber daya yang diperlukan kepada pesaing atau konsumen</td></tr><tr><td>Blokade Pengetahuan</td><td>Menggunakan posisi monopoli pengetahuan untuk memblokir metode kultivasi dasar dan memaksa pelajar membayar biaya tinggi</td></tr></tbody></table><h3 id="_3-konsentrasi-pelaku-usaha" tabindex="-1">(3) Konsentrasi Pelaku Usaha <a class="header-anchor" href="#_3-konsentrasi-pelaku-usaha" aria-label="Permalink to &quot;(3) Konsentrasi Pelaku Usaha&quot;">​</a></h3><p>Konsentrasi pelaku usaha merujuk pada situasi berikut: penggabungan pelaku usaha; akuisisi kendali atas pelaku usaha lain melalui perolehan saham atau aset; akuisisi kendali atas pelaku usaha lain atau kemampuan untuk memberikan pengaruh menentukan terhadap pelaku usaha lain melalui kontrak, dll.</p><p>Konsentrasi pelaku usaha yang mencapai standar pelaporan harus dilaporkan sebelumnya kepada lembaga penegak anti-monopoli, dan yang tidak dilaporkan tidak boleh dilaksanakan. Dalam meninjau konsentrasi pelaku usaha, lembaga penegak anti-monopoli harus mempertimbangkan faktor-faktor berikut:</p><ol><li>Pangsa pasar pelaku usaha yang terlibat dalam konsentrasi di pasar terkait dan kekuatan kendali mereka terhadap pasar.</li><li>Konsentrasi pasar dari pasar terkait.</li><li>Dampak konsentrasi pelaku usaha terhadap masuknya pasar dan kemajuan teknologi.</li><li>Dampak konsentrasi pelaku usaha terhadap konsumen dan pelaku usaha terkait lainnya.</li><li>Dampak konsentrasi pelaku usaha terhadap keterbukaan sumber daya kultivasi dan penyebaran pengetahuan.</li><li>Dampak konsentrasi pelaku usaha terhadap perkembangan ekonomi nasional dan kemajuan bersama semua ras.</li></ol><h3 id="_4-penyalahgunaan-kekuasaan-administratif-untuk-mengecualikan-atau-membatasi-persaingan" tabindex="-1">(4) Penyalahgunaan Kekuasaan Administratif untuk Mengecualikan atau Membatasi Persaingan <a class="header-anchor" href="#_4-penyalahgunaan-kekuasaan-administratif-untuk-mengecualikan-atau-membatasi-persaingan" aria-label="Permalink to &quot;(4) Penyalahgunaan Kekuasaan Administratif untuk Mengecualikan atau Membatasi Persaingan&quot;">​</a></h3><p>Lembaga administratif dan organisasi yang diberi wewenang oleh hukum dan peraturan untuk menjalankan fungsi pengelolaan urusan publik tidak boleh menyalahgunakan kekuasaan administratif untuk melakukan praktik berikut:</p><ol><li>Membatasi atau secara terselubung membatasi unit atau individu untuk mengoperasikan, membeli, atau menggunakan barang yang disediakan oleh pelaku usaha yang mereka tunjuk.</li><li>Menghambat peredaran bebas barang antar wilayah dan antar bidang.</li><li>Mengecualikan atau membatasi pelaku usaha dari wilayah lain atau bidang lain untuk berpartisipasi dalam tender dan lelang lokal.</li><li>Mengecualikan atau membatasi pelaku usaha dari wilayah lain atau bidang lain untuk berinvestasi secara lokal atau mendirikan cabang.</li><li>Memaksa pelaku usaha untuk melakukan praktik monopoli yang diatur dalam hukum ini.</li><li>Menyusun peraturan dengan konten yang mengecualikan atau membatasi persaingan.</li></ol><h2 id="iii-aturan-anti-monopoli-khusus-di-bidang-kultivasi" tabindex="-1">III. Aturan Anti-Monopoli Khusus di Bidang Kultivasi <a class="header-anchor" href="#iii-aturan-anti-monopoli-khusus-di-bidang-kultivasi" aria-label="Permalink to &quot;III. Aturan Anti-Monopoli Khusus di Bidang Kultivasi&quot;">​</a></h2><p>Bidang kultivasi adalah bidang kunci anti-monopoli dalam peradaban simbiosis jangkar, dan hukum ini menetapkan aturan khusus:</p><ol><li><strong>Kewajiban Keterbukaan Metode Dasar</strong>: Metode dasar dari tiga ratus sistem kultivasi asal termasuk dalam pengetahuan publik, dan tidak ada organisasi atau individu yang boleh memonopoli, memblokir, atau mengajarkannya dengan biaya.</li><li><strong>Distribusi Adil Sumber Daya Kultivasi</strong>: Sumber daya kultivasi publik didistribusikan secara adil melalui mekanisme kontrak produksi bersama, dan dilarang bagi sekte atau individu untuk memonopoli sumber daya kultivasi berkualitas tinggi.</li><li><strong>Larangan Diskriminasi Kultivasi</strong>: Sekte kultivasi tidak boleh menetapkan kondisi diskriminatif berdasarkan ras, asal-usul, tingkat kultivasi, dll. dalam penerimaan dan pengajaran.</li><li><strong>Kewajiban Berbagi Pengetahuan Tingkat Lanjut</strong>: Kultivator yang mencapai standar makhluk tertinggi di bidang memiliki kewajiban untuk berbagi dengan masyarakat pengalaman kultivasi dan hasil penelitian mereka, dengan syarat melindungi kekayaan intelektual yang wajar.</li><li><strong>Anti-Monopoli Pengembangan Bidang</strong>: Hak pengembangan bidang baru didistribusikan melalui persaingan terbuka, dan dilarang bagi sedikit kekuatan untuk memonopoli hak pengembangan bidang.</li></ol><h2 id="iv-lembaga-penegak-anti-monopoli" tabindex="-1">IV. Lembaga Penegak Anti-Monopoli <a class="header-anchor" href="#iv-lembaga-penegak-anti-monopoli" aria-label="Permalink to &quot;IV. Lembaga Penegak Anti-Monopoli&quot;">​</a></h2><p>Negara mendirikan lembaga penegak anti-monopoli, bertanggung jawab atas penegakan anti-monopoli, dan menjalankan fungsi berikut:</p><ol><li>Meneliti dan menyusun kebijakan persaingan terkait.</li><li>Mengorganisir investigasi dan evaluasi situasi persaingan pasar secara keseluruhan, dan menerbitkan laporan evaluasi.</li><li>Menyusun dan menerbitkan pedoman anti-monopoli.</li><li>Mengoordinasikan pekerjaan penegakan administratif anti-monopoli.</li><li>Menyelidiki dan menghukum kasus perjanjian monopoli, penyalahgunaan posisi dominan pasar, implementasi ilegal konsentrasi pelaku usaha, dll.</li><li>Menyelidiki dan menghukum praktik penyalahgunaan kekuasaan administratif untuk mengecualikan atau membatasi persaingan.</li></ol><p>Lembaga penegak anti-monopoli menjalankan fungsinya secara independen sesuai hukum, tanpa campur tangan dari lembaga administratif, organisasi sosial, dan individu.</p><h2 id="v-tanggung-jawab-hukum" tabindex="-1">V. Tanggung Jawab Hukum <a class="header-anchor" href="#v-tanggung-jawab-hukum" aria-label="Permalink to &quot;V. Tanggung Jawab Hukum&quot;">​</a></h2><p>Kegiatan yang melanggar ketentuan hukum ini menanggung tanggung jawab berikut sesuai tingkat keparahan pelanggaran:</p><ul><li>Menyepakati dan melaksanakan perjanjian monopoli, diperintahkan menghentikan praktik ilegal, menyita keuntungan ilegal, dan didenda 1% hingga 10% dari pendapatan penjualan tahun sebelumnya.</li><li>Menyalahgunakan posisi dominan pasar, diperintahkan menghentikan praktik ilegal, menyita keuntungan ilegal, dan didenda 1% hingga 10% dari pendapatan penjualan tahun sebelumnya.</li><li>Melaksanakan konsentrasi pelaku usaha secara ilegal, diperintahkan menghentikan konsentrasi, menjual saham atau aset dalam batas waktu, mengalihkan bisnis dalam batas waktu, dan didenda hingga 500.000 yuan.</li><li>Menyalahgunakan kekuasaan administratif untuk mengecualikan atau membatasi persaingan, lembaga yang lebih tinggi memerintahkan perbaikan, dan personel yang bertanggung jawab langsung serta personel bertanggung jawab langsung lainnya diberikan hukuman sesuai hukum.</li><li>Praktik monopoli yang menyebabkan kerugian bagi orang lain menanggung tanggung jawab ganti rugi perdata sesuai hukum.</li><li>Kasus parah yang构成 kejahatan dituntut tanggung jawab pidana sesuai hukum.</li></ul><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>《Hukum Anti-Monopoli》 adalah senjata hukum dari anti-predasi peradaban simbiosis jangkar di bidang ekonomi dan kultivasi. Dengan mengatur perjanjian monopoli, penyalahgunaan posisi dominan pasar, konsentrasi pelaku usaha, dan monopoli administratif, terutama menetapkan aturan khusus untuk monopoli sumber daya kultivasi dan monopoli pengetahuan, ia memastikan persaingan pasar dan keterbukaan yang adil dari sumber daya kultivasi, mencegah monopoli menjadi bentuk baru eksploitasi semua makhluk, dan menjaga lingkungan institusional persaingan yang adil untuk kemajuan bersama semua ras.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen terkait&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Prinsip Umum Konstitusi Simbiosis)</li><li>42-消费者保护法 (Hukum Perlindungan Konsumen)</li><li>18-修炼资源开放机制 (Mekanisme Keterbukaan Sumber Daya Kultivasi)</li><li>04-反掠夺主义核心论纲 (Program Inti Anti-Predasi)</li></ul>',35)])])}const g=n(u,[["render",s]]);export{p as __pageData,g as default};
